def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_run += 1
        else:
            break

    dd_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            dd_run += 1
        else:
            break

    W = min(8, max(1, n - 1))
    start = max(1, n - W)

    c_to_c = 0
    c_to_d = 0
    d_to_c = 0
    d_to_d = 0

    for i in range(start, n):
        prev_my = history[i - 1][0]
        curr_opp = history[i][1]
        if prev_my == 'C':
            if curr_opp == 'C':
                c_to_c += 1
            else:
                c_to_d += 1
        else:
            if curr_opp == 'C':
                d_to_c += 1
            else:
                d_to_d += 1

    R = min(10, n)
    recent_opp_c = 0
    recent_opp_d = 0

    for i in range(n - R, n):
        if history[i][1] == 'C':
            recent_opp_c += 1
        else:
            recent_opp_d += 1

    soft = d_to_c > 0 and d_to_c >= d_to_d

    persistent = (
        not soft and
        opp_d_run >= 8 and
        c_to_c == 0 and
        c_to_d >= 3
    )

    overwhelming = (
        not soft and
        recent_opp_d >= 9 and
        recent_opp_c <= 1 and
        c_to_d >= 2 and
        d_to_c == 0
    )

    if soft:
        return 'D'

    if persistent or overwhelming:
        return 'D'

    if last_opp == 'C':
        # After our own defection against a cooperator, wait one round
        # to see whether the opponent actually punishes us.
        if last_my == 'D' and d_to_c == 0:
            return 'C'

        # One cautious exploitation probe against long cooperative stretches
        # that have not yet shown any response to our defects.
        if n >= 25 and d_to_c + d_to_d == 0 and recent_opp_c >= 7:
            if rng.random() < 0.75:
                return 'D'

        return 'C'

    # Opponent just defected.
    if opp_d_run == 1 and last_my == 'C':
        # Forgive the first unprovoked defection. This avoids punishment
        # cycles against forgiving TFT-like opponents.
        return 'C'

    if last_my == 'D':
        # Against near-unconditional defenders, do not break too early.
        if opp_d_run >= 8 or (recent_opp_d >= 9 and recent_opp_c <= 1):
            return 'D'

        # Try to restore cooperation after short mutual-defection streaks,
        # especially if our recent C signals have been rewarded before.
        if dd_run >= 2 or c_to_c >= c_to_d:
            return 'C'

        return 'D'

    # last_my == 'C' and opponent has a nontrivial D-run.
    # Give one more explicit forgiveness attempt at length 5 when the
    # previous mutual-defection streak has already been broken.
    if opp_d_run == 5 and dd_run == 0:
        return 'C'

    # If the opponent has shown repeated responsiveness to cooperation,
    # a longer D-run may be temporary retaliation; reset rather than punish.
    if opp_d_run >= 6 and c_to_c >= c_to_d + 3 and recent_opp_c >= 3:
        return 'C'

    # Otherwise, punish sustained unresponsive defection.
    return 'D'
